export type PassKind = "observer" | "builder" | "host";

export type PassInput = {
  handle: string;
  secret?: string;
};

export type PassRecord = {
  id: string;
  kind: PassKind;
  handle: string;
  secret: string;
};

export type AuditSink = {
  publish(message: string): void;
};

export class PassRegistry {
  private readonly records = new Map<string, PassRecord>();
  private readonly handles = new Set<string>();
  private readonly counters: Record<PassKind, number> = {
    observer: 1,
    builder: 1,
    host: 1
  };

  get(id: string): PassRecord | undefined {
    const record = this.records.get(id);
    return record === undefined ? undefined : { ...record };
  }

  list(): PassRecord[] {
    return [...this.records.values()].map((record) => ({ ...record }));
  }

  issue(kind: PassKind, input: PassInput, sink: AuditSink): PassRecord {
    const handle = input.handle.trim();
    if (handle.length === 0) throw new TypeError("handle must not be empty");
    const normalized = handle.toLowerCase();
    if (this.handles.has(normalized)) throw new Error("duplicate handle");

    const prefix: Record<PassKind, string> = {
      observer: "O",
      builder: "B",
      host: "H"
    };
    const sequence = this.counters[kind]++;
    const id = `${prefix[kind]}-${String(sequence).padStart(4, "0")}`;
    const suppliedSecret = input.secret?.trim() ?? "";
    const record: PassRecord = {
      id,
      kind,
      handle,
      secret: suppliedSecret.length === 0 ? "welcome-2026" : suppliedSecret
    };

    sink.publish(`pass-created:${id}:${normalized}`);
    this.records.set(id, { ...record });
    this.handles.add(normalized);
    return { ...record };
  }
}

export function createObserverPass(
  registry: PassRegistry,
  input: PassInput,
  sink: AuditSink
): PassRecord {
  return registry.issue("observer", input, sink);
}

export function createBuilderPass(
  registry: PassRegistry,
  input: PassInput,
  sink: AuditSink
): PassRecord {
  return registry.issue("builder", input, sink);
}

export function createHostPass(
  registry: PassRegistry,
  input: PassInput,
  sink: AuditSink
): PassRecord {
  return registry.issue("host", input, sink);
}

