import { PassRegistry, createObserverPass, createBuilderPass, createHostPass } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

function captureError(fn: () => unknown): unknown {
  try {
    fn();
  } catch (error) {
    return error;
  }
  return undefined;
}

const events: string[] = [];
const sink = { publish(message: string): void { events.push(message); } };
const registry = new PassRegistry();

const observer = createObserverPass(registry, { handle: '  Forge  ' }, sink);
deepEqual(observer, { id: 'O-0001', kind: 'observer', handle: 'Forge', secret: 'welcome-2026' }, 'observer pass must trim handle and use the default secret');
deepEqual(events, ['pass-created:O-0001:forge'], 'observer creation must publish the normalized audit event');

const builder = createBuilderPass(registry, { handle: 'Builder', secret: '  custom-secret  ' }, sink);
deepEqual(builder, { id: 'B-0001', kind: 'builder', handle: 'Builder', secret: 'custom-secret' }, 'builder pass must trim a supplied secret');
const host = createHostPass(registry, { handle: 'Host', secret: '   ' }, sink);
deepEqual(host, { id: 'H-0001', kind: 'host', handle: 'Host', secret: 'welcome-2026' }, 'blank secret must use the default');

deepEqual(events, [
  'pass-created:O-0001:forge',
  'pass-created:B-0001:builder',
  'pass-created:H-0001:host'
], 'audit events must preserve successful creation order');
deepEqual(registry.list(), [observer, builder, host], 'list must preserve successful creation order');

const duplicateError = captureError(() => createHostPass(registry, { handle: ' fOrGe ' }, sink));
assert(duplicateError instanceof Error, 'handles must be unique case-insensitively across kinds');
assert(registry.list().length === 3, 'duplicate rejection must not alter registry state');
assert(captureError(() => createObserverPass(registry, { handle: '   ' }, sink)) instanceof TypeError, 'blank handles must throw TypeError');

const returned = registry.get('O-0001');
assert(returned !== observer, 'get must return a fresh record');
(returned as unknown as { handle: string }).handle = 'Changed';
deepEqual(registry.get('O-0001'), observer, 'mutating a get result must not affect stored records');

const listA = registry.list();
const listB = registry.list();
assert(listA !== listB, 'list arrays must be fresh');
assert(listA[0] !== listB[0], 'records in list results must be fresh');
(listA as unknown as Array<{ handle: string }>)[0].handle = 'Changed';
deepEqual(registry.list(), [observer, builder, host], 'mutating list records must not affect registry state');

const rollbackRegistry = new PassRegistry();
const failingSink = { publish(_message: string): void { throw new Error('audit unavailable'); } };
assert(captureError(() => createObserverPass(rollbackRegistry, { handle: 'First' }, failingSink)) instanceof Error, 'publish failures must propagate');
deepEqual(rollbackRegistry.list(), [], 'publish failure must leave the registry empty');
const afterFailureEvents: string[] = [];
const afterFailure = createObserverPass(rollbackRegistry, { handle: 'First' }, {
  publish(message: string): void { afterFailureEvents.push(message); }
});
assert((afterFailure as unknown as { id: string }).id === 'O-0001', 'publish failure must not consume a sequence number');
deepEqual(afterFailureEvents, ['pass-created:O-0001:first'], 'retry after rollback must publish the unconsumed ID');

const input = { handle: 'Mutable', secret: 'secret' };
const isolated = createBuilderPass(rollbackRegistry, input, sink);
input.handle = 'Changed';
input.secret = 'Changed';
deepEqual(rollbackRegistry.get((isolated as unknown as { id: string }).id), isolated, 'input objects must not be stored by reference');

